AWS API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_api_gateway, "AWS API Gateway") {
    Component(HTTP_Route_Resolver, "HTTP Route Resolver", "AWS API Gateway (HTTP API v2)", "Receives screening payloads via REST/JSON over HTTPS and handles low-overhead HTTP/2 ingress.")
    Component(Native_JWT_Authorizer, "Native JWT Authorizer", "AWS API Gateway Native JWT Authorizer", "Validates bearer tokens at the edge without custom compute overhead.")
    Component(VPC_Link_Integration, "VPC Link Integration", "AWS API Gateway VPC Link", "Forwards sanitized payloads via gRPC over HTTP/2 to internal services.")
}

Rel(HTTP_Route_Resolver, Native_JWT_Authorizer, "Validates bearer tokens", "Internal Evaluation")
Rel(HTTP_Route_Resolver, VPC_Link_Integration, "Forwards sanitized payloads", "gRPC over HTTP/2")
@enduml

Audit & Streaming Pipeline.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(audit_streaming_pipeline, "Audit & Streaming Pipeline") {
    Component(Amazon Kinesis Data Streams, "Amazon Kinesis Data Streams", "Amazon Kinesis Data Streams", "Ingests real-time pre-redacted audit events.")
    Component(Amazon Kinesis Firehose, "Amazon Kinesis Firehose", "Amazon Kinesis Firehose", "Batches and streams audit logs to persistent storage.")
    Component(AWS Lambda, "AWS Lambda", "AWS Lambda", "Processes and routes audit events within the streaming pipeline.")
}

Rel(Amazon Kinesis Data Streams, Amazon Kinesis Firehose, "Batches and forwards stream data", "")
Rel(Amazon Kinesis Firehose, AWS Lambda, "Invokes processing functions or handles error routing", "")

@enduml
